namespace {
class RtGrid : public QFrame {
public:
  QGridLayout *grid=new QGridLayout(this);QList<QWidget *> cards;int columns{8};
  RtGrid(){grid->setSizeConstraint(QLayout::SetNoConstraint);setSizePolicy(QSizePolicy::Expanding,QSizePolicy::Preferred);}
  QSize minimumSizeHint() const override {return {280,grid->minimumSize().height()};}
  QSize sizeHint() const override {return {1000,grid->sizeHint().height()};}
  void arrange(){int count=qBound(2,width()/145,8);if(count==columns&&!cards.isEmpty()&&grid->count()==cards.size())return;columns=count;for(auto card:cards)grid->removeWidget(card);for(int i=0;i<cards.size();++i)grid->addWidget(cards[i],i/columns,i%columns);updateGeometry();}
  void resizeEvent(QResizeEvent *event) override {QFrame::resizeEvent(event);arrange();}
};
QFrame *surface(QLayout *layout) {auto f=new QFrame;f->setProperty("card",true);layout->addWidget(f);return f;}
QLabel *heading(const QString &text,QLayout *layout) {auto l=new QLabel(text);l->setProperty("tone","cardtitle");layout->addWidget(l);return l;}
}
QWidget *Window::saveControls(bool compact) {
  auto frame=new QFrame;frame->setProperty("card",!compact);auto layout=new QVBoxLayout(frame);if(compact)layout->setContentsMargins(0,0,0,0);
  auto row=new QHBoxLayout;layout->addLayout(row);
  auto folder=new QLineEdit(settings.value("exportFolder",desktop::defaultExportDirectory()).toString());folder->setObjectName("csvFolderEdit");folder->setAccessibleName("CSV output folder");
  auto name=new QLineEdit(settings.value("nextRunName",desktop::suggestedRunName(folder->text())).toString());name->setObjectName("runNameEdit");name->setAccessibleName("Run name");name->setMaximumWidth(240);
  csvFolderEdit=folder;runNameEdit=name;
  auto browse=new QPushButton("Browse…");browse->setObjectName("browseCsvFolder");
  if(compact){name->setMaximumWidth(QWIDGETSIZE_MAX);row->addWidget(new QLabel("Run name:"));row->addWidget(name,1);auto folderRow=new QHBoxLayout;layout->addLayout(folderRow);folderRow->addWidget(new QLabel("CSV folder:"));folderRow->addWidget(folder,1);folderRow->addWidget(browse);}
  else {row->addWidget(new QLabel("CSV folder:"));row->addWidget(folder,2);row->addWidget(browse);row->addWidget(new QLabel("Run name:"));row->addWidget(name,1);}
  auto preview=new QLabel;preview->setWordWrap(true);preview->setProperty("tone","muted");outputPreview=preview;layout->addWidget(preview);
  const auto refresh=[this,folder,name,preview]{settings.setValue("exportFolder",folder->text().trimmed());settings.setValue("nextRunName",name->text().trimmed());preview->setProperty("outputText","Outputs (complete session, match by record #): "+name->text()+"_EXT.csv + "+name->text()+"_INT.csv   |   Replay sessions: "+sessionDir);preview->setText(preview->property("outputText").toString());};
  connect(folder,&QLineEdit::textChanged,frame,refresh);connect(name,&QLineEdit::textChanged,frame,refresh);
  connect(browse,&QPushButton::clicked,frame,[this,folder]{const auto dir=QFileDialog::getExistingDirectory(this,"CSV output folder",folder->text());if(!dir.isEmpty())folder->setText(dir);});refresh();
  const auto lockInputs=[this,folder,name,browse,preview]{const bool enabled=!(savingSession&&sessionSaveState.startsWith("Exporting"));folder->setEnabled(enabled);name->setEnabled(enabled);browse->setEnabled(enabled);preview->setText(preview->property("outputText").toString()+(currentFile.isEmpty()?QString():"\nLive capture ID: "+QFileInfo(currentFile).baseName())+(sessionSaveState.isEmpty()?QString():"   |   Save: "+sessionSaveState));preview->setStyleSheet(sessionSaveState=="Save failed"?"color:#a73d32;":"");};lockInputs();connect(&tick,&QTimer::timeout,frame,lockInputs);
  if(!compact) {
    auto save=new QPushButton("Stop && save");save->setObjectName("stopSaveButton");save->setProperty("primary",true);row->addWidget(save);monitorCsv=save;connect(save,&QPushButton::clicked,this,[this]{stopAndSave();});
    auto actions=new QHBoxLayout;actions->addStretch();layout->addLayout(actions);
    auto mode=new QComboBox;mode->setObjectName("workspaceLayout");mode->addItem("Movable windows","windows");mode->addItem("Tabs","tabs");mode->setCurrentIndex(settings.value("monitorLayout","windows").toString()=="tabs"?1:0);
    actions->addWidget(new QLabel("Layout:"));actions->addWidget(mode);
    auto tile=new QPushButton("Tile");auto cascade=new QPushButton("Cascade");actions->addWidget(tile);actions->addWidget(cascade);
    const auto layoutActions=[mode,tile,cascade]{const bool windows=mode->currentData().toString()=="windows";tile->setEnabled(windows);cascade->setEnabled(windows);};layoutActions();connect(mode,&QComboBox::currentIndexChanged,frame,[layoutActions](int){layoutActions();});
    connect(mode,&QComboBox::currentIndexChanged,frame,[this,mode](int){persistMonitorWorkspace();settings.setValue("monitorLayout",mode->currentData());if(monitorWorkspace)applyMonitorLayout();});
    connect(tile,&QPushButton::clicked,frame,[this]{if(monitorWorkspace){for(auto w:channelWindows)w->showNormal();monitorWorkspace->tileSubWindows();}});
    connect(cascade,&QPushButton::clicked,frame,[this]{if(monitorWorkspace){for(auto w:channelWindows)w->showNormal();monitorWorkspace->cascadeSubWindows();}});
  }
  return frame;
}
bool Window::chooseSaveDestination() {
  QDialog dialog(this);dialog.setWindowTitle("Save Internal and External CSVs");dialog.setMinimumWidth(620);auto layout=new QVBoxLayout(&dialog);
  auto note=new QLabel("The complete recording is retained for replay. Choose where to save both CSV files.");note->setWordWrap(true);layout->addWidget(note);
  auto form=new QFormLayout;layout->addLayout(form);QLineEdit folder(settings.value("exportFolder").toString()),name(settings.value("nextRunName").toString());folder.setObjectName("saveDialogFolder");name.setObjectName("saveDialogRunName");form->addRow("CSV folder",&folder);form->addRow("Run name",&name);
  auto shortcuts=new QHBoxLayout;layout->addLayout(shortcuts);
  for(const auto &item:QList<QPair<QString,QStandardPaths::StandardLocation>>{{"Desktop",QStandardPaths::DesktopLocation},{"Documents",QStandardPaths::DocumentsLocation}}) {auto button=new QPushButton(item.first);shortcuts->addWidget(button);connect(button,&QPushButton::clicked,&dialog,[&folder,item]{folder.setText(QStandardPaths::writableLocation(item.second));});}
  auto browse=new QPushButton("Browse…");shortcuts->addWidget(browse);connect(browse,&QPushButton::clicked,&dialog,[this,&folder]{auto path=QFileDialog::getExistingDirectory(this,"CSV folder",folder.text());if(!path.isEmpty())folder.setText(path);});
  auto error=new QLabel;error->setWordWrap(true);error->setStyleSheet("color:#a73d32");layout->addWidget(error);auto buttons=new QDialogButtonBox(QDialogButtonBox::Save|QDialogButtonBox::Cancel);layout->addWidget(buttons);
  connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{auto problem=desktop::validateRunName(name.text().trimmed());if(folder.text().trimmed().isEmpty())problem="Choose a CSV folder.";if(!problem.isEmpty()){error->setText(problem);return;}dialog.accept();});
  if(dialog.exec()!=QDialog::Accepted)return false;
  if(csvFolderEdit)csvFolderEdit->setText(folder.text().trimmed());if(runNameEdit)runNameEdit->setText(name.text().trimmed());settings.setValue("exportFolder",folder.text().trimmed());settings.setValue("nextRunName",name.text().trimmed());return true;
}
void Window::welcome() {
  heading("Prepare a monitoring run",pageLayout);auto intro=new QLabel("Choose channels and a CSV destination. You can edit the run name and destination while monitoring.");intro->setWordWrap(true);pageLayout->addWidget(intro);
  auto row=new QHBoxLayout;pageLayout->addLayout(row);auto prepare=surface(row);row->setStretch(0,3);auto body=new QVBoxLayout(prepare);heading("Next run",body);body->addWidget(saveControls(true));
  auto buttons=new QHBoxLayout;body->addLayout(buttons);auto setup=new QPushButton("Review device setup");setup->setProperty("primary",true);auto open=new QPushButton("Open recorded session…");buttons->addWidget(setup);buttons->addWidget(open);connect(setup,&QPushButton::clicked,this,[this]{navigate(2);});connect(open,&QPushButton::clicked,this,&Window::openSession);
  auto readiness=surface(row);row->setStretch(1,2);auto ready=new QVBoxLayout(readiness);heading("Hardware readiness",ready);auto evidence=new QLabel; evidence->setWordWrap(true);ready->addWidget(evidence,1);auto details=new QPushButton("Device details");ready->addWidget(details);connect(details,&QPushButton::clicked,this,[this]{navigate(2);});
  const auto refresh=[this,evidence]{const auto metrics=backend.acquisition.metrics(false);evidence->setText(QString("Windows device: %1\n\nDriver / SDK: %2\n\nLogical channels: %3 / %4\n\nMonitor: %5").arg(hardwareDiscovery.isEmpty()?"Check in device setup":hardwareDiscovery.value("physical_presence").toString()=="unknown"?QString("Unknown — enumeration incomplete"):QString::number(hardwareDiscovery.value("detected_devices").toInt())+" detected").arg(hardwareDiscovery.isEmpty()?"Check in device setup":"See measured connection checks").arg(backend.captureConfig.logicalDevices[0]).arg(backend.captureConfig.logicalDevices[1]).arg(backend.acquisition.active()?"Recording":metrics.failed?"Connection failed":"Stopped"));};refresh();connect(&tick,&QTimer::timeout,evidence,refresh);
  auto recent=surface(pageLayout);auto items=new QVBoxLayout(recent);heading("Recent sessions",items);auto table=new QTableWidget;table->setColumnCount(4);table->setHorizontalHeaderLabels({"Name","Date / Time","Recording location","Open"});table->horizontalHeader()->setSectionResizeMode(2,QHeaderView::Stretch);table->verticalHeader()->hide();table->verticalHeader()->setDefaultSectionSize(46);table->setEditTriggers(QAbstractItemView::NoEditTriggers);items->addWidget(table);const auto files=recordingFiles().mid(0,4);table->setRowCount(files.size());for(int i=0;i<files.size();++i){const QFileInfo info(files[i]);table->setItem(i,0,new QTableWidgetItem(desktop::sessionDisplayName(files[i])));table->setItem(i,1,new QTableWidgetItem(info.lastModified().toString("dd MMM HH:mm")));table->setItem(i,2,new QTableWidgetItem(info.absolutePath()));auto button=new QPushButton("Open…");table->setCellWidget(i,3,button);connect(button,&QPushButton::clicked,this,[this,path=files[i]]{loadSession(path);});}table->setMinimumHeight(250);
  auto links=new QHBoxLayout;items->addLayout(links);auto simulation=new QPushButton("Offline simulation…");auto folder=new QPushButton("Open replay folder");links->addWidget(simulation);links->addWidget(folder);links->addStretch();connect(simulation,&QPushButton::clicked,this,[this]{navigate(2);if(auto source=content->findChild<QComboBox *>("sourceMode"))source->setCurrentIndex(1);});connect(folder,&QPushButton::clicked,this,[this]{QDesktopServices::openUrl(QUrl::fromLocalFile(sessionDir));});
}
void Window::dashboard() {
  auto legend=new QLabel;rtLegend=legend;legend->setWordWrap(true);legend->setProperty("tone","notice");pageLayout->addWidget(legend);
  auto gridSurface=new RtGrid;gridSurface->setProperty("card",true);pageLayout->addWidget(gridSurface);auto grid=gridSurface->grid;grid->setSpacing(8);
  for(int rt=0;rt<32;++rt){auto card=new QFrame;card->setProperty("card",true);card->setProperty("rtIndex",rt);card->setMinimumHeight(125);auto body=new QVBoxLayout(card);body->setContentsMargins(12,12,12,12);body->setSpacing(8);auto select=new QPushButton(rt==31?"31 · Broadcast":QString("RT %1").arg(rt,2,10,QChar('0')));select->setProperty("rtSelector",true);select->setFlat(true);body->addWidget(select);connect(select,&QPushButton::clicked,this,[this,rt]{selectedRt=rt;refreshRtDashboard();});
    for(int ch=0;ch<2;++ch){auto l=new QLabel;body->addWidget(l);if(rt<31)rtLights[ch][rt]=l;else l->setText(ch?"CH2 · Broadcast commands":"CH1 · Broadcast commands");}gridSurface->cards<<card;grid->addWidget(card,rt/8,rt%8);}
  rtDetail=new QLabel;rtDetail->setWordWrap(true);rtDetail->setProperty("tone","notice");pageLayout->addWidget(rtDetail);auto note=new QLabel("Passive observation reports responses seen during this run. Silent terminals cannot be identified as physically connected.");note->setWordWrap(true);note->setProperty("tone","muted");pageLayout->addWidget(note);refreshRtDashboard();
}
void Window::refreshRtDashboard() {
  if(!rtLegend)return;const auto metrics=backend.acquisition.metrics(false);const auto &activity=backend.replaySource?replayActivity:metrics.rtActivity;
  rtLegend->setText(QString("%1 · %2   |   ● Green: valid response observed this run   ○ Grey: not observed").arg(backend.replaySource?"Replay":backend.captureConfig.hardware?"Passive hardware monitoring":"SIMULATION").arg(backend.acquisition.active()?"Recording":metrics.failed?"Capture error — inspect diagnostics":"Stopped / recorded observations"));
  for(int ch=0;ch<2;++ch)for(int rt=0;rt<31;++rt)if(auto label=rtLights[ch][rt]){const auto &v=activity.channels[ch][rt];label->setText(QString("<span style='font-size:22px;color:%1'>●</span> <span style='font-size:12px'>CH%2 %3</span>").arg(v.responses?"#15803d":"#778797").arg(ch+1).arg(ch?"Internal":"External"));label->setProperty("responseObserved",v.responses>0);label->setAccessibleName(QString("RT %1, channel %2: %3").arg(rt).arg(ch+1).arg(v.responses?"valid response observed":"no response observed"));label->setToolTip(v.responses?QString("%1 valid responses · Bus %2 · last device time %3").arg(v.responses).arg(v.buses==3?"A + B":v.buses==1?"A":"B").arg(stamp(v.lastNs)):"No valid response observed during this run");}
  for(auto card:content->findChildren<QFrame *>())if(card->property("rtIndex").isValid()) {const int rt=card->property("rtIndex").toInt();desktop::workspaceState(card,"selectedRt",rt==selectedRt);desktop::workspaceState(card,"observedRt",rt<31&&(activity.channels[0][rt].responses||activity.channels[1][rt].responses));}
  if(selectedRt==31){rtDetail->setText(QString("Broadcast commands: CH1 %1 · CH2 %2. Broadcast address 31 does not return a terminal response.").arg(activity.broadcasts[0]).arg(activity.broadcasts[1]));return;}
  QStringList detail;for(int ch=0;ch<2;++ch){const auto &v=activity.channels[ch][selectedRt];detail<<QString("CH%1 %2: %3").arg(ch+1).arg(ch?"Internal":"External").arg(v.responses?QString("%1 responses · last device time %2 · Bus %3").arg(v.responses).arg(stamp(v.lastNs)).arg(v.buses==3?"A + B":v.buses==1?"A":"B"):"No response observed");}rtDetail->setText(QString("RT %1\n").arg(selectedRt,2,10,QChar('0'))+detail.join("\n"));
}
void Window::device() {
  auto sourceCard=surface(pageLayout);auto sourceRow=new QHBoxLayout(sourceCard);heading("Source",sourceRow);
  auto source=new QComboBox;source->setObjectName("sourceMode");source->addItems({"DDC hardware · passive monitoring","Offline simulation · generated test traffic"});source->setCurrentIndex(backend.captureConfig.hardware?0:1);sourceRow->addWidget(source,1);
  auto scan=new QPushButton("Rescan DDC");scan->setObjectName("scanButton");sourceRow->addWidget(scan);
  auto mainRow=new QHBoxLayout;pageLayout->addLayout(mainRow);auto deviceCard=surface(mainRow);auto devices=new QVBoxLayout(deviceCard);heading("Windows devices",devices);
  auto table=new QTableWidget;table->setObjectName("discoveredDdcDevices");table->setColumnCount(4);table->setHorizontalHeaderLabels({"Device","Hardware ID","Driver","PnP status"});table->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);table->verticalHeader()->hide();table->setEditTriggers(QAbstractItemView::NoEditTriggers);table->setMinimumHeight(170);devices->addWidget(table,1);
  auto manager=new QPushButton("Open DDC Card Manager");devices->addWidget(manager);connect(manager,&QPushButton::clicked,this,&Window::openCardManager);
  auto mapping=new QLabel("Verify physical channel mappings in Card Manager. Enter vendor logical numbers below; Windows discovery does not establish that association.");mapping->setWordWrap(true);mapping->setProperty("tone","muted");devices->addWidget(mapping);
  auto channels=surface(mainRow);auto channelBody=new QVBoxLayout(channels);heading("Channel assignments",channelBody);auto channelRow=new QHBoxLayout;channelBody->addLayout(channelRow);
  QList<QWidget *> controls{source};
  for(int ch=0;ch<2;++ch){auto group=new QGroupBox(QString("Channel %1 / %2").arg(ch+1).arg(ch?"Internal":"External"));group->setProperty("channelRole",ch?"internal":"external");channelRow->addWidget(group);auto body=new QVBoxLayout(group);body->addWidget(new QLabel("Logical device number"));auto logical=new QSpinBox;logical->setObjectName(QString("logicalChannel%1").arg(ch+1));logical->setRange(0,31);logical->setValue(backend.captureConfig.logicalDevices[ch]);body->addWidget(logical);controls<<logical;
    connect(logical,&QSpinBox::valueChanged,group,[this,ch](int value){backend.captureConfig.logicalDevices[ch]=value;settings.setValue(QString("logicalChannel%1").arg(ch+1),value);configurationChanged();});
    for(int bus=0;bus<2;++bus){auto check=new QCheckBox(bus?"Bus B":"Bus A");const auto key=QString("channel%1Bus %2").arg(ch+1).arg(bus?"B":"A");check->setObjectName(QString("channel%1Bus%2").arg(ch+1).arg(bus?"B":"A"));check->setChecked(settings.value(key,true).toBool());body->addWidget(check);controls<<check;connect(check,&QCheckBox::toggled,group,[this,key](bool on){settings.setValue(key,on);configurationChanged();});}body->addStretch();}
  auto simulationRow=new QHBoxLayout;channelBody->addLayout(simulationRow);simulationRow->addWidget(new QLabel("Simulation events/s"));auto rate=new QSpinBox;rate->setObjectName("simulatorRate");rate->setRange(1,100000);rate->setValue(backend.captureConfig.simulatorRate);simulationRow->addWidget(rate);controls<<rate;connect(rate,&QSpinBox::valueChanged,this,[this](int value){backend.captureConfig.simulatorRate=value;settings.setValue("simulatorRate",value);});
  auto checkCard=surface(pageLayout);auto checks=new QVBoxLayout(checkCard);heading("Connection checks",checks);auto summary=new QLabel;summary->setWordWrap(true);summary->setObjectName("connectionChecks");checks->addWidget(summary);
  auto explanation=new QLabel("The monitor interface is selected from the device's reported MT / MTI capabilities during connection. No ICD is required for raw monitoring.");explanation->setWordWrap(true);explanation->setProperty("tone","muted");checks->addWidget(explanation);
  auto action=new QHBoxLayout;checks->addLayout(action);auto run=new QLabel("Replay sessions: "+sessionDir);run->setWordWrap(true);action->addWidget(run,1);auto arm=new QPushButton;arm->setObjectName("armButton");arm->setProperty("primary",true);action->addWidget(arm);connect(arm,&QPushButton::clicked,this,[this]{if(backend.captureConfig.hardware)connectDevices();else startCapture();});
  auto detailsButton=new QPushButton("Technical details ▸");detailsButton->setCheckable(true);checks->addWidget(detailsButton,0,Qt::AlignLeft);auto details=new QWidget;auto detailLayout=new QVBoxLayout(details);auto runtime=new QLineEdit(QString::fromStdWString(backend.captureConfig.runtime.wstring()));runtime->setObjectName("runtimePath");runtime->setPlaceholderText("DDC SDK folder or emacepl.dll — blank uses this PC's configured / detected SDK");runtime->setAccessibleName("DDC SDK folder or runtime DLL");runtime->setToolTip("An explicit path takes priority. Otherwise DDC_SDK_ROOT is used before installed SDK discovery. No SDK version number is fixed.");detailLayout->addWidget(runtime);controls<<runtime;auto evidence=new QLabel;evidence->setWordWrap(true);evidence->setTextInteractionFlags(Qt::TextSelectableByMouse);detailLayout->addWidget(evidence);checks->addWidget(details);details->hide();connect(detailsButton,&QPushButton::toggled,details,&QWidget::setVisible);
  connect(runtime,&QLineEdit::textChanged,this,[this](const QString &path){backend.captureConfig.runtime=std::filesystem::path(path.toStdWString());settings.setValue("ddcRuntime",path);configurationChanged();});
  connect(source,&QComboBox::currentIndexChanged,this,[this](int index){backend.captureConfig.hardware=index==0;settings.setValue("captureSource",index==0?"DDC":"SIMULATOR");configurationChanged();refreshOperatorState();});
  connect(scan,&QPushButton::clicked,this,[this,evidence]{rescanDdc(evidence);});
  auto previous=std::make_shared<QJsonObject>();const auto refresh=[this,table,summary,evidence,arm,scan,controls,previous]{
    const auto metrics=backend.acquisition.metrics(false);for(auto control:controls)control->setEnabled(!backend.acquisition.active()&&!connecting&&!savingSession);scan->setEnabled(!discoveryRunning);arm->setEnabled(!backend.acquisition.active()&&!connecting&&!savingSession);arm->setText(connecting?"Checking devices…":backend.captureConfig.hardware?"Connect devices":"Start offline simulation");
    if(*previous!=hardwareDiscovery){*previous=hardwareDiscovery;const auto rows=hardwareDiscovery.value("devices").toArray();table->setRowCount(rows.size());for(int i=0;i<rows.size();++i){const auto o=rows[i].toObject();const QStringList values{o.value("name").toString(),o.value("hardware_ids").toString(),o.value("driver_service").toString()+" / "+o.value("driver_version").toString(),o.value("pnp_status").toString()+" / problem "+QString::number(o.value("pnp_problem").toInt())};for(int col=0;col<4;++col){auto cell=new QTableWidgetItem(values[col]);cell->setToolTip(values[col]);table->setItem(i,col,cell);}}evidence->setText(desktop::discoverySummary(hardwareDiscovery));}
    const auto states=[&](int c){const auto &d=metrics.devices[c];const auto count=metrics.sourceCounts[c*2]+metrics.sourceCounts[c*2+1];switch(d.phase){case aero::DevicePhase::Monitoring:return count?QString("Receiving %1 records").arg(count):QString("Initialized — no traffic yet");case aero::DevicePhase::Simulating:return QString("Simulation — %1 records").arg(count);case aero::DevicePhase::Failed:return "Failed: "+QString::fromStdString(d.message);case aero::DevicePhase::Checking:return QString("Checking logical channel");case aero::DevicePhase::Ready:return QString("Configured");case aero::DevicePhase::Disabled:return QString("Disabled");default:return QString("Not initialized");}};
    QStringList drivers;for(auto item:hardwareDiscovery.value("devices").toArray()){auto d=item.toObject();drivers<<d.value("driver_service").toString()+" "+d.value("driver_version").toString()+" / "+d.value("pnp_status").toString();}
    summary->setText(QString("Windows device: %1\nDriver binding: %2\nSDK runtime: %3\nLogical assignment: CH1 = %4, CH2 = %5 (vendor mapping required)\nMonitor CH1: %6\nMonitor CH2: %7").arg(discoveryRunning?"Scanning…":hardwareDiscovery.isEmpty()?"Not scanned":hardwareDiscovery.value("physical_presence").toString()=="unknown"?QString("Unknown — enumeration incomplete"):QString::number(hardwareDiscovery.value("detected_devices").toInt())+" detected").arg(drivers.isEmpty()?"Not confirmed":drivers.join("; ")).arg(hardwareDiscovery.isEmpty()?"Not inspected":hardwareDiscovery.value("runtime_available").toBool()?"Available — does not prove device connectivity":"Unavailable").arg(backend.captureConfig.logicalDevices[0]).arg(backend.captureConfig.logicalDevices[1]).arg(states(0),states(1)));
  };refresh();connect(&tick,&QTimer::timeout,summary,refresh);if(hardwareDiscovery.isEmpty()&&!discoveryRunning)QTimer::singleShot(0,evidence,[this,evidence]{rescanDdc(evidence);});
}
